import {ensureScene,entities,pixelPoints,makeProp,PALETTE,clampPosition} from './layout-model.mjs?v=0.21.0';
import {ensureInstallation,exposedPorts,perimeterAnchor,deleteRoute} from './installation-model.mjs?v=0.21.0';
import {routeLayer,routeControls,routeInspector,installRoutes,refreshRoutes} from './installation-room.mjs?v=0.21.0';
let api,chosen='',propId='prop-smiley',showGrid=true,showPixelLines=true,zoom=1,drag=null,panDrag=null,roomWire=null,viewport={left:0,top:0};
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(t,a,c='btn')=>`<button type="button" class="${c}" data-room="${a}">${t}</button>`;
const field=(label,value,key,type='number',min=0,max=100,step='any')=>`<label>${label}<input type="${type}" value="${E(value)}" data-room-field="${key}" ${type==='number'?`required min="${min}" max="${max}" step="${step}"`:'maxlength="200"'}></label>`;
const pick=(label,value,key,items)=>`<label>${label}<select data-room-field="${key}">${items.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${E(t)}</option>`).join('')}</select></label>`;
function restoreViewport(){const sc=document.querySelector('.room-scroll');if(sc){sc.scrollLeft=viewport.left;sc.scrollTop=viewport.top;}}
function setZoom(next,clientX,clientY){const sc=document.querySelector('.room-scroll'),svg=sc?.querySelector('#room-canvas');if(!sc||!svg)return;next=Math.max(.5,Math.min(3,Math.round(next*100)/100));const rect=sc.getBoundingClientRect(),x=clientX==null?sc.clientWidth/2:clientX-rect.left,y=clientY==null?sc.clientHeight/2:clientY-rect.top,ratio=next/zoom;zoom=next;svg.style.width=svg.style.minWidth=zoom*100+'%';sc.scrollLeft=(sc.scrollLeft+x)*ratio-x;sc.scrollTop=(sc.scrollTop+y)*ratio-y;viewport={left:sc.scrollLeft,top:sc.scrollTop};const read=document.querySelector('[data-room-zoom]');if(read)read.textContent=Math.round(zoom*100)+'%';}
function homeViewport(){const sc=document.querySelector('.room-scroll'),svg=sc?.querySelector('#room-canvas');if(!sc||!svg)return;zoom=1;svg.style.width=svg.style.minWidth='100%';const read=document.querySelector('[data-room-zoom]');if(read)read.textContent='100%';requestAnimationFrame(()=>{sc.scrollLeft=Math.max(0,(sc.scrollWidth-sc.clientWidth)/2);sc.scrollTop=Math.max(0,(sc.scrollHeight-sc.clientHeight)/2);viewport={left:sc.scrollLeft,top:sc.scrollTop};});}
function propSvg(pr,count=pr.count,numbered=false){const points=pixelPoints(pr,count);return `${pr.reference?`<image href="${pr.reference}" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid meet" opacity=".55"/>`:''}${showPixelLines&&points.length>1?`<polyline points="${points.map(pt=>`${pt.x*100},${pt.y*100}`).join(' ')}" fill="none" stroke="${pr.color}" stroke-opacity=".55" stroke-width=".8"/>`:''}${points.map((pt,i)=>`<circle cx="${pt.x*100}" cy="${pt.y*100}" r="${numbered?1.5:1.8}" fill="${pr.color}"/>${numbered&&points.length<=150?`<text x="${pt.x*100+1.8}" y="${pt.y*100-1.5}" font-size="2.3" fill="#677b78">${i+1}</text>`:''}`).join('')}`;}
function floodSvg(count,color){return Array.from({length:Math.min(count,8)},(_,i)=>{const x=8+i*(84/Math.max(1,Math.min(count,8)));return `<g transform="translate(${x} 48)"><path d="M0 1L-5 30H10L5 1" fill="${color}" opacity=".16"/><rect x="-4" y="-5" width="12" height="8" rx="1" fill="#263c3d"/><rect x="-2" y="2" width="8" height="3" fill="${color}"/></g>`;}).join('');}
export function roomView(p){ensureInstallation(p);ensureScene(p);requestAnimationFrame(restoreViewport);const es=entities(p);if(!es.some(e=>e.key===chosen))chosen=es[0]?.key;const e=es.find(e=>e.key===chosen),v=p.scene.placements[chosen];return `<div class="room-toolbar"><div><strong>Room layout</strong><span>Bird’s-eye · drag objects to position · drag empty space to pan</span></div><div>${b('+ Field device','field-library','btn')}${b(showGrid?'Grid on':'Grid off','grid','btn '+(showGrid?'pressed':''))}</div></div>${routeControls(p)}<div class="room-workspace"><div class="room-panel panel"><div class="room-dimensions"><span>${p.scene.width} m × ${p.scene.depth} m</span><span>${p.scene.snap?'Snap '+p.scene.snap+' m':'Free positioning'}</span></div><div class="room-stage"><div class="room-scroll"><svg id="room-canvas" viewBox="0 0 ${p.scene.width*100} ${p.scene.depth*100}" style="width:${zoom*100}%;min-width:${zoom*100}%" role="img" aria-label="Bird’s-eye room layout. Drag objects to position, drag empty space to pan, or use the mouse wheel to zoom."><defs><pattern id="room-grid" width="100" height="100" patternUnits="userSpaceOnUse"><path d="M100 0H0V100" fill="none" stroke="#dce5e4" stroke-width="1"/></pattern></defs><rect width="100%" height="100%" fill="#f9fbfa"/>${showGrid?'<rect width="100%" height="100%" fill="url(#room-grid)"/>':''}<rect x="3" y="3" width="${p.scene.width*100-6}" height="${p.scene.depth*100-6}" fill="none" stroke="#9cafad" stroke-width="6"/><g id="room-routes">${routeLayer(p)}</g>${es.map(en=>node(p,en)).join('')}</svg></div><div class="room-camera" role="group" aria-label="Room view controls"><button type="button" data-room="zoom-out" aria-label="Zoom out" title="Zoom out">−</button><span data-room-zoom aria-live="polite">${Math.round(zoom*100)}%</span><button type="button" data-room="zoom-in" aria-label="Zoom in" title="Zoom in">+</button><button type="button" data-room="home" aria-label="Reset zoom and recenter room" title="Reset zoom and recenter">⌂</button></div></div><div class="room-key"><span><i></i> Data <i class="room-power-key"></i> Power <i class="room-inject-key"></i> Injection</span><span>Mouse wheel zooms · drag empty space to pan</span></div></div><aside class="panel room-inspector"><div class="inspector-title"><h3>Layout inspector</h3><span class="pill">2D</span></div><div class="inspector-body">${e?`<span class="room-type">${e.type==='segment'?'PIXEL GROUP':e.type.toUpperCase()}</span><h3>${E(e.name)}</h3>${pick('Selected object',chosen,'selection',es.map(x=>[x.key,x.name+' · '+x.type]))}<div class="two">${field('X position (m)',v.x,'item.x','number',0,p.scene.width)}${field('Y position (m)',v.y,'item.y','number',0,p.scene.depth)}</div><div class="two">${field('Width (m)',v.width,'item.width','number',.1,50)}${field('Depth (m)',v.height,'item.height','number',.1,50)}</div>${field('Rotation (degrees)',v.rotation,'item.rotation','number',-360,360)}${field(e.type==='segment'?'String / prop colour':'Box colour',v.color,'item.color','color')}<div class="colour-swatches">${PALETTE.map(c=>`<button data-room="colour:${c}" style="background:${c}" aria-label="Use colour ${c}"></button>`).join('')}</div>${e.type==='box'?b('Edit box internals','open-box:'+e.id):''}${e.type==='field'?b('Remove field device','delete-field:'+e.id,'text-btn danger'):''}${e.type==='segment'?`${b('Edit wiring for this group','wire:'+e.chain.id)}<p class="micro">${e.o.count} ${E(e.o.kind)} pixels${e.o.propId?' · '+E(p.props.find(pr=>pr.id===e.o.propId)?.name):''}. Size and colour are layout labels, not output brightness or LED colours.</p>`:'<p class="micro">Box dimensions are a layout reference. Edit electrical ratings in Hardware & power.</p>'}`:''}${routeInspector(p,api.getLibrary())}<div class="section-label">ROOM SETTINGS</div><div class="two">${field('Width (m)',p.scene.width,'scene.width','number',2,100)}${field('Depth (m)',p.scene.depth,'scene.depth','number',2,100)}</div>${pick('Snap to grid',p.scene.snap,'scene.snap',[[0,'Off'],[.05,'5 cm'],[.1,'10 cm'],[.25,'25 cm'],[.5,'50 cm'],[1,'1 m']])}<p class="micro">Drag any box or pixel group. Arrow keys move a selected object; Shift moves 1 m. Dimensions and positions are saved with your project.</p></div></aside></div>`;}
function boxVisual(box,w,h){const items=box.components,n=items.length,cols=Math.max(1,Math.ceil(Math.sqrt(n*w/Math.max(h,1)))),rows=Math.max(1,Math.ceil(n/cols)),header=18,cellW=w/cols,cellH=(h-header)/rows,labels=api.getProject().installation.showLabels;return `<g><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="4" fill="#193f39" stroke="#4f806a" stroke-width="3"/>${labels?`<text x="${-w/2+8}" y="${-h/2+13}" fill="white" font-size="13" font-weight="700">${E(box.name.slice(0,30))}</text>`:''}${items.map((part,i)=>{const x=-w/2+(i%cols)*cellW,y=-h/2+header+Math.floor(i/cols)*cellH,c=part.snapshot.color||'#4b8a76';return `<g><rect x="${x+1}" y="${y+1}" width="${cellW-2}" height="${cellH-2}" fill="${E(c)}" fill-opacity=".9" stroke="white" stroke-width="1"/>${labels?`<text x="${x+5}" y="${y+Math.min(16,cellH/2)}" font-size="11" fill="white" paint-order="stroke" stroke="#153d36" stroke-width="2">${E(part.snapshot.name.slice(0,Math.max(4,Math.floor(cellW/6))))}</text>`:''}<title>${E(part.snapshot.name)} · ${E(part.snapshot.ports.length)} ports</title></g>`;}).join('')}${n||!labels?'':'<text text-anchor="middle" y="5" fill="white" font-size="11">EMPTY BOX</text>'}${exposedPorts(box).map(({component,port,edge})=>{const point=perimeterAnchor(api.getProject(),box.id,component.id,port.id);if(!point)return '';const placement=api.getProject().scene.placements['box:'+box.id],x=(point.x-placement.x)*100,y=(point.y-placement.y)*100,label=(component.snapshot.name+' '+port.label).slice(0,24),tx=x+(edge==='left'?-7:edge==='right'?7:0),ty=y+(edge==='top'?-7:edge==='bottom'?11:3),anchor=edge==='left'?'end':edge==='right'?'start':'middle';return `<g><circle class="room-external-node" data-room-port="${E(box.id)}:${E(component.id)}:${E(port.id)}" cx="${x}" cy="${y}" r="5" fill="${E(component.snapshot.color||'#4b8a76')}" stroke="white" stroke-width="1.5"><title>${E(box.name)} → ${E(component.snapshot.name)} → ${E(port.label)} (${E(port.type)})</title></circle>${labels?`<text class="room-port-label" x="${tx}" y="${ty}" text-anchor="${anchor}">${E(label)}</text>`:''}</g>`;}).join('')}</g>`;}
function node(p,e){const v=p.scene.placements[e.key],pr=p.props.find(pr=>pr.id===e.o.propId),is=e.type==='segment',w=v.width*100,h=v.height*100,labels=p.installation.showLabels;return `<g data-room-node="${E(e.key)}" tabindex="0" role="button" aria-label="Move ${E(e.name)}" transform="translate(${v.x*100} ${v.y*100})" class="room-object ${chosen===e.key?'chosen':''}"><g transform="rotate(${v.rotation})"><rect x="${-w/2-6}" y="${-h/2-6}" width="${w+12}" height="${h+12}" rx="7" fill="transparent" class="selection-ring" stroke="${chosen===e.key?'#153f3d':'transparent'}" stroke-width="2"/>${is?`<svg x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" viewBox="0 0 100 100" preserveAspectRatio="none">${e.o.kind==='flood'&&!pr?floodSvg(e.o.count,v.color):propSvg(pr?{...pr,color:v.color}:{shape:'line',count:e.o.count,columns:Math.min(e.o.count,8),color:v.color},e.o.count)}</svg><rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" fill="transparent"/>`:`${e.type==='box'?boxVisual(e.o,w,h):e.type==='field'?`<path d="M0 ${-h/2}L${w/2} 0L0 ${h/2}L${-w/2} 0Z" fill="${E(v.color)}" stroke="#244d43" stroke-width="3"/>${labels?`<text text-anchor="middle" y="4" font-size="12" fill="white">${E(e.o.snapshot.icon||'◆')}</text>`:''}`:e.type==='psu'?`<rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="3" fill="#e7f0e8" stroke="${v.color}" stroke-width="4"/><path d="M${w/2-10} ${-h/2}v${h}" stroke="${v.color}" stroke-width="5"/>`:e.type==='distro'?`<path d="M${-w/2} ${-h/2}h${w-8}l8 8v${h-8}h${-w}z" fill="#e9f1f4" stroke="${v.color}" stroke-width="4"/>`:e.type==='controller'?`<rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="10" fill="#173f34" stroke="${v.color}" stroke-width="4"/>`:`<rect x="${-w/2}" y="${-h/2}" width="${w}" height="${h}" rx="6" fill="${v.color}"/>`}${labels?`<text text-anchor="middle" y="4" fill="${e.type==='psu'||e.type==='distro'?'#28483d':'white'}" font-size="${Math.min(14,w/5)}" font-weight="700">${e.type==='box'||e.type==='field'?'':({controller:'CTRL',psu:'PSU',distro:'DIST',aux:'I/O'})[e.type]}</text>`:''}`}</g>${labels?`<text class="room-object-label" x="0" y="${h/2+16}" text-anchor="middle">${E(e.name.length>30?e.name.slice(0,28)+'…':e.name)}</text>${is?`<text class="room-object-detail" x="0" y="${h/2+30}" text-anchor="middle">P${e.chain.port} · ${e.o.count} pixels</text>`:''}`:''}</g>`;}
export function propsView(p){ensureScene(p);if(!p.props.some(x=>x.id===propId))propId=p.props[0]?.id;const pr=p.props.find(x=>x.id===propId);return `<div class="room-note">Props are reusable pixel layouts. Place an instance on a controller port to include its pixels in the electrical plan. Imported images and SVGs are visual references; mark the actual pixel positions over them.</div><div class="prop-page"><aside class="panel prop-library">${p.props.map(x=>`<button data-room="prop:${x.id}" class="prop-tile ${propId===x.id?'active':''}"><svg viewBox="0 0 100 100" aria-hidden="true">${propSvg(x)}</svg><span><strong>${E(x.name)}</strong><small>${x.count} pixels · ${E(x.shape)}</small></span></button>`).join('')}${b('+ New prop','new-prop')}</aside><section class="panel prop-editor">${pr?`<div class="props-header"><div><div class="eyebrow">PROP DESIGNER</div><h2>${E(pr.name)}</h2></div>${b('Place in room','place-prop','btn primary')}</div><div class="prop-edit-grid"><div><div class="prop-canvas ${pr.shape==='custom'?'marking':''}"><svg id="prop-canvas" viewBox="0 0 100 100" role="img" aria-label="Prop pixel layout${pr.shape==='custom'?'. Click to add a pixel.':''}">${propSvg(pr,pr.count,true)}</svg></div><div class="prop-stat"><span>${pr.count} pixels / ${pr.count*pr.channels} channels</span><span>${(pr.count*pr.watts).toFixed(1)} W full white</span></div><div class="prop-actions">${b('Import image / SVG','upload-reference')}${b(showPixelLines?'Hide pixel lines':'Show pixel lines','pixel-lines')}${b('Reset to one point','reset-points','text-btn danger')}${pr.shape==='custom'?b('Undo last pixel','undo-pixel')+b('Clear pixels','clear-pixels','text-btn danger'):b('Edit individual pixels','make-custom')}</div>${pr.reference?`<div class="prop-reference">Reference: ${E(pr.referenceName)} · embedded in project ${b('Remove','remove-reference','text-btn')}</div>`:''}<p class="prop-help">${pr.shape==='custom'?'Click the drawing to add pixels in wiring order. Use Undo last pixel to correct a point.':'Choose a shape and pixel count, then edit individual points if needed.'} Numbering follows data order. ${pr.count>600?'The preview displays the first 600 points.':''}</p></div><div class="prop-form">${field('Prop name',pr.name,'prop.name','text')}${pick('Pixel layout',pr.shape,'prop.shape',[['smiley','Smiley face'],['circle','Circle'],['star','Star'],['line','Straight string'],['grid','Grid / matrix'],['custom','Custom pixel points']])}${pr.shape==='custom'?`<div class="readout"><span>Marked pixel count</span><strong>${pr.count}</strong></div>`:field('Pixel count',pr.count,'prop.count','number',1,5000,1)}${pr.shape==='grid'?field('Grid columns',pr.columns,'prop.columns','number',1,100,1):''}<div class="two">${field('Width (m)',pr.width,'prop.width','number',.1,50)}${field('Height (m)',pr.height,'prop.height','number',.1,50)}</div>${field('Prop colour',pr.color,'prop.color','color')}${pick('Pixel type',pr.kind,'prop.kind',[['seed','Seeds'],['bullet','Bullets']])}${field('Full-white W / pixel',pr.watts,'prop.watts','number',.001,1000)}${pick('Channels / pixel',pr.channels,'prop.channels',[[3,'RGB · 3'],[4,'RGBW · 4']])}<p class="prop-help">These are template defaults. Placed props have their own pixel count, colour, dimensions and electrical settings. Their shape and reference stay linked to this template.</p></div></div><div class="prop-actions">${b('Duplicate prop','duplicate-prop')}${b('Delete template','delete-prop','text-btn danger')}</div>`:'<div class="prop-empty">Create a prop to begin.</div>'}</section></div>`;}
export function installRoom(a){api=a;installRoutes(a);document.addEventListener('click',onClick);document.addEventListener('change',onChange);document.addEventListener('pointerdown',down);document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);document.addEventListener('pointercancel',up);document.addEventListener('wheel',wheel,{passive:false});document.addEventListener('scroll',rememberViewport,true);document.addEventListener('keydown',key);const file=document.createElement('input');file.id='prop-reference-file';file.type='file';file.accept='image/png,image/jpeg,image/webp,image/svg+xml';file.hidden=true;document.body.append(file);file.addEventListener('change',importReference);}
function completeRoomWire(key){if(!roomWire||!key||!key.startsWith('field:')&&!key.startsWith('segment:'))return;const source=roomWire;roomWire=null;api.linkRoom(source,key);}
function onClick(ev){const external=ev.target.closest('[data-room-port]');if(external){const [boxId,componentId,portId]=external.dataset.roomPort.split(':');roomWire={boxId,componentId,portId};api.toast('Choose a field device or pixel group to connect.');return;}const node=ev.target.closest('[data-room-node]');if(node&&roomWire){completeRoomWire(node.dataset.roomNode);return;}const canvas=ev.target.closest('#prop-canvas');if(canvas){const pr=api.getProject().props.find(x=>x.id===propId);if(pr?.shape==='custom'){const pt=canvas.createSVGPoint();pt.x=ev.clientX;pt.y=ev.clientY;const a=pt.matrixTransform(canvas.getScreenCTM().inverse());if(a.x>=0&&a.x<=100&&a.y>=0&&a.y<=100)api.transact(()=>{pr.points.push({x:+(a.x/100).toFixed(5),y:+(a.y/100).toFixed(5)});pr.count=pr.points.length;});}return;}const el=ev.target.closest('[data-room]');if(!el)return;const [action,id]=el.dataset.room.split(':'),p=api.getProject(),pr=p.props.find(x=>x.id===propId);if(action==='field-library'){api.showFieldLibrary();return;}if(action==='delete-field'){api.transact(()=>{p.installation.fieldDevices=p.installation.fieldDevices.filter(x=>x.id!==id);for(const link of p.installation.connections.filter(x=>x.toKey==='field:'+id||x.fromKey==='field:'+id))deleteRoute(p,'custom:'+link.id);});return;}if(action==='grid')showGrid=!showGrid;else if(action==='pixel-lines')showPixelLines=!showPixelLines;else if(action==='zoom-in'){setZoom(zoom+.25);return;}else if(action==='zoom-out'){setZoom(zoom-.25);return;}else if(action==='home'){homeViewport();return;}else if(action==='colour'){api.transact(()=>p.scene.placements[chosen].color=id);return;}else if(action==='wire'){api.wiring(id);return;}else if(action==='open-box'){api.showBoxes(id);return;}else if(action==='prop')propId=id;else if(action==='new-prop'){api.transact(()=>{const item=makeProp();item.name='New prop';p.props.push(item);propId=item.id;});return;}else if(action==='duplicate-prop'){api.transact(()=>{const item=structuredClone(pr);item.id=makeProp().id;item.name+=' copy';p.props.push(item);propId=item.id;});return;}else if(action==='make-custom'){api.transact(()=>{if(pr.count>600)throw Error('Reduce the template to 600 pixels or fewer before editing individual points.');pr.points=pixelPoints(pr);pr.shape='custom';pr.count=pr.points.length;});return;}else if(action==='undo-pixel'){api.transact(()=>{pr.points.pop();pr.count=pr.points.length;});return;}else if(action==='reset-points'){api.confirmAction('Reset prop drawing?','This replaces the template with one pixel at the centre. Placed instances keep their electrical count and will show a layout mismatch until updated.',()=>{pr.shape='custom';pr.points=[{x:.5,y:.5}];pr.count=1;});return;}else if(action==='clear-pixels'){api.confirmAction('Clear marked pixels?','This clears the template drawing. Existing placed props keep their pixel count.',()=>{pr.points=[];pr.count=0;});return;}else if(action==='delete-prop'){api.confirmAction('Delete prop template?','Placed instances will become ordinary pixel strings with the same pixel count and electrical settings.',()=>{for(const ch of p.chains)for(const s of ch.segments)if(s.propId===pr.id)delete s.propId;p.props=p.props.filter(x=>x.id!==pr.id);});return;}else if(action==='upload-reference'){document.querySelector('#prop-reference-file').dataset.target=pr.id;document.querySelector('#prop-reference-file').click();return;}else if(action==='remove-reference'){api.transact(()=>{pr.reference='';pr.referenceName='';});return;}else if(action==='place-prop'){place(pr,p);return;}else return;api.render();}
function onChange(ev){const t=ev.target,k=t.dataset.roomField;if(!k)return;if(!t.checkValidity()){t.reportValidity();return;}if(k==='selection'){chosen=t.value;api.render();return;}api.transact(()=>{const p=api.getProject();if(k.startsWith('scene.')){p.scene[k.slice(6)]=+t.value;for(const v of Object.values(p.scene.placements))Object.assign(v,clampPosition(v,p.scene));}else if(k.startsWith('item.')){const key=k.slice(5);p.scene.placements[chosen][key]=key==='color'?t.value:+t.value;}else if(k.startsWith('prop.')){const pr=p.props.find(x=>x.id===propId),key=k.slice(5);if(key==='shape'&&t.value==='custom'){if(pr.count>600)throw Error('Reduce the template to 600 pixels or fewer first.');pr.points=pixelPoints(pr);}pr[key]=typeof pr[key]==='number'?+t.value:t.value;if(key==='shape')pr.count=pr.shape==='custom'?pr.points.length:Math.max(1,pr.count);}});}
function locationAt(ev,svg){const pt=svg.createSVGPoint();pt.x=ev.clientX;pt.y=ev.clientY;const a=pt.matrixTransform(svg.getScreenCTM().inverse());return {x:a.x/100,y:a.y/100};}
function down(ev){if(ev.target.closest('[data-room-port]')){const [boxId,componentId,portId]=ev.target.closest('[data-room-port]').dataset.roomPort.split(':');roomWire={boxId,componentId,portId};return;}const el=ev.target.closest('[data-room-node]');if(el&&ev.button===0){const p=api.getProject(),svg=el.closest('svg#room-canvas'),key=el.dataset.roomNode,v=p.scene.placements[key],pt=locationAt(ev,svg);chosen=key;drag={svg,el,key,start:{...v},offset:{x:pt.x-v.x,y:pt.y-v.y},pointer:ev.pointerId};el.setPointerCapture(ev.pointerId);ev.preventDefault();return;}const sc=ev.target.closest('.room-scroll');if(!sc||ev.button!==0||!ev.target.closest('#room-canvas')||ev.target.closest('.physical-route,[data-route-pivot],[data-route-endpoint]'))return;panDrag={sc,pointer:ev.pointerId,x:ev.clientX,y:ev.clientY,left:sc.scrollLeft,top:sc.scrollTop};sc.setPointerCapture(ev.pointerId);sc.classList.add('panning');ev.preventDefault();}
function move(ev){if(panDrag&&ev.pointerId===panDrag.pointer){panDrag.sc.scrollLeft=panDrag.left-(ev.clientX-panDrag.x);panDrag.sc.scrollTop=panDrag.top-(ev.clientY-panDrag.y);return;}if(!drag||ev.pointerId!==drag.pointer)return;const p=api.getProject(),pt=locationAt(ev,drag.svg),s=p.scene.snap;let pos={x:pt.x-drag.offset.x,y:pt.y-drag.offset.y};if(s){pos.x=Math.round(pos.x/s)*s;pos.y=Math.round(pos.y/s)*s;}pos=clampPosition(pos,p.scene);const v=p.scene.placements[drag.key];v.x=+pos.x.toFixed(3);v.y=+pos.y.toFixed(3);drag.el.setAttribute('transform',`translate(${v.x*100} ${v.y*100})`);refreshRoutes();}
function up(ev){if(panDrag&&ev.pointerId===panDrag.pointer){panDrag.sc.classList.remove('panning');viewport={left:panDrag.sc.scrollLeft,top:panDrag.sc.scrollTop};panDrag=null;return;}if(roomWire&&!drag){const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-room-node]');if(target)completeRoomWire(target.dataset.roomNode);return;}if(!drag||ev.pointerId!==drag.pointer)return;if(ev.type==='pointercancel')Object.assign(api.getProject().scene.placements[drag.key],drag.start);drag=null;api.save();api.render();}
function wheel(ev){const sc=ev.target.closest('.room-scroll');if(!sc)return;ev.preventDefault();setZoom(zoom*(ev.deltaY<0?1.15:1/1.15),ev.clientX,ev.clientY);}
function rememberViewport(ev){if(ev.target.matches?.('.room-scroll'))viewport={left:ev.target.scrollLeft,top:ev.target.scrollTop};}
function key(ev){const el=ev.target.closest('[data-room-node]');if(!el)return;if(['Enter',' '].includes(ev.key)){chosen=el.dataset.roomNode;api.render();return;}const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[ev.key];if(!delta)return;ev.preventDefault();chosen=el.dataset.roomNode;api.transact(()=>{const p=api.getProject(),v=p.scene.placements[chosen],step=ev.shiftKey?1:p.scene.snap||.1;Object.assign(v,clampPosition({x:v.x+step*delta[0],y:v.y+step*delta[1]},p.scene));});document.querySelector(`[data-room-node="${CSS.escape(chosen)}"]`)?.focus();}
function place(pr,p){if(!pr.count){api.toast('Mark at least one pixel before placing this prop.');return;}const free=[];for(const c of p.controllers)for(let port=1;port<=api.boardPorts(c);port++)if(!p.chains.some(ch=>ch.controller===c.id&&ch.port===port))free.push([c.id+'|'+port,c.name+' · port '+port]);const options=[...free.map(([id,name])=>`<option value="new|${id}">New output: ${E(name)}</option>`),...p.chains.map(ch=>`<option value="append|${ch.id}">Append to ${E(ch.name)} · P${ch.port}</option>`)];if(!options.length){api.toast('Add a controller first.');return;}api.modal('Place '+E(pr.name),`<p>Add ${pr.count} ${E(pr.kind)} pixels (${(pr.count*pr.watts).toFixed(1)} W full white) to the electrical plan.</p><label>Data connection<select name="target">${options.join('')}</select></label>`,f=>{api.transact(()=>{const [mode,id,port]=f.get('target').split('|'),s=api.newSegment(pr.kind);Object.assign(s,{count:pr.count,watts:pr.watts,channels:pr.channels,propId:pr.id});if(mode==='new')p.chains.push({id:'r-'+Math.random().toString(36).slice(2,10),name:pr.name,controller:id,port:+port,segments:[s]});else p.chains.find(c=>c.id===id).segments.push(s);ensureScene(p);chosen='segment:'+s.id;Object.assign(p.scene.placements[chosen],{x:p.scene.width/2,y:p.scene.depth/2,width:pr.width,height:pr.height,color:pr.color});});api.showRoom();});}
export function sanitizeSvg(text){if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('SVG document declarations are not supported. Export a plain SVG.');const doc=new DOMParser().parseFromString(text,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('This file is not a valid SVG.');const tags=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon','text','tspan','defs','linearGradient','radialGradient','stop','clipPath','use','title','desc']);const attrs=new Set(['id','viewBox','width','height','x','y','x1','y1','x2','y2','cx','cy','r','rx','ry','d','points','fill','stroke','stroke-width','stroke-linecap','stroke-linejoin','fill-rule','opacity','fill-opacity','stroke-opacity','transform','font-size','font-family','font-weight','text-anchor','dominant-baseline','offset','stop-color','stop-opacity','gradientUnits','gradientTransform','preserveAspectRatio','clip-path','href','xmlns']);for(const el of [...doc.querySelectorAll('*')]){if(!tags.has(el.localName)){el.remove();continue;}for(const attr of [...el.attributes]){if(!attrs.has(attr.name)||(attr.name==='href'&&!attr.value.startsWith('#'))||(/url\s*\(/i.test(attr.value)&&!/^url\(#[\w-]+\)$/.test(attr.value))||/javascript:|data:|https?:|@import|expression/i.test(attr.value)&&attr.name!=='xmlns')el.removeAttribute(attr.name);}}doc.documentElement.setAttribute('xmlns','http://www.w3.org/2000/svg');if(!doc.documentElement.getAttribute('width'))doc.documentElement.setAttribute('width','1000');if(!doc.documentElement.getAttribute('height'))doc.documentElement.setAttribute('height','1000');return new XMLSerializer().serializeToString(doc);}
async function importReference(ev){const input=ev.target,file=input.files[0],target=input.dataset.target;input.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('Choose a reference smaller than 5 MB.');let blob=file;if(file.type==='image/svg+xml'||/\.svg$/i.test(file.name))blob=new Blob([sanitizeSvg(await file.text())],{type:'image/svg+xml'});else if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Choose a PNG, JPEG, WebP or SVG.');const url=URL.createObjectURL(blob);let img;try{img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Could not read this image. Try exporting a plain SVG or PNG.'));image.src=url;});}finally{URL.revokeObjectURL(url);}if(!img.naturalWidth||!img.naturalHeight)throw Error('The image has no dimensions.');const scale=Math.min(1,960/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.85);const saved=api.transact(()=>{const pr=api.getProject().props.find(x=>x.id===target);if(!pr)throw Error('The prop was removed.');pr.reference=data;pr.referenceName=file.name.slice(0,200);});if(saved)api.toast('Reference imported. Use Edit individual pixels to mark or adjust positions.');}catch(err){api.toast(err.message);}}
